   <title>Notification Preferences</title>
   <style>
     :root {
       --color-bg: #0b1020;
       --color-surface: #141b31;
       --color-surface-strong: #1a2442;
       --color-text: #eef2ff;
       --color-muted-text: #b6c2e1;
