       --color-button-text: #081224;
       --color-shadow: #050814;
       --color-success: #7ef0b0;
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
