       position: absolute;
       opacity: 0;
       inset: 0;
       margin: 0;
     }

     .radio-option label {
       display: flex;
       align-items: center;
       gap: 0.85rem;
       width: 100%;
       padding: 0.95rem 1rem;
       border: 1px solid var(--color-border);
       border-radius: 0.95rem;
