     .radio-option input:hover + label,
     .radio-option label:hover {
       border-color: var(--color-border-strong);
       transform: translateY(-1px);
     }

     .radio-option input:checked + label {
       border-color: var(--color-border-strong);
       background: #13203d;
     }

     .radio-option input:checked + label::before {
       background: radial-gradient(circle, var(--color-accent-strong) 0 45%, transparent 50%);
       box-shadow: inset 0 0 0 1px var(--color-accent-strong);
     }

     .radio-option input:focus-visible + label,
     button:focus-visible {
       outline: 3px solid var(--color-focus);
       outline-offset: 3px;
     }

     .actions {
       display: flex;
       align-items: center;
       gap: 1rem;
       flex-wrap: wrap;
     }

     button {
       border: 0;
       border-radius: 999px;
       padding: 0.9rem 1.3rem;
       background: linear-gradient(135deg, var(--color-accent-strong), var(--color-accent));
       color: var(--color-button-text);
       font: inherit;
       font-weight: 700;
       cursor: pointer;
     }

     button:hover {
       filter: brightness(1.08);
     }

     .status-message {
       margin: 0;
       min-height: 1.5rem;
       color: var(--color-success);
       font-weight: 600;
     }

     @media (max-width: 30rem) {
       .panel {
         padding: 1.5rem;
       }
     }

     @media (forced-colors: active) {
       body,
       .panel,
       .form-field,
       .radio-option label,
       button {
         background: Canvas;
         color: CanvasText;
         border-color: ButtonBorder;
         box-shadow: none;
       }

       .radio-option label::before {
         border-color: ButtonText;
       }

       .radio-option input:checked + label::before {
         background: Highlight;
         box-shadow: inset 0 0 0 1px Highlight;
       }

       .radio-option input:focus-visible + label,
       button:focus-visible,
       .skip-link:focus {
         outline: 2px solid Highlight;
       }

       .skip-link {
         background: ButtonFace;
