      --color-surface-strong: #1a2442;
      --color-text: #eef2ff;
      --color-muted-text: #b6c2e1;
      --color-border: #334267;
      --color-border-strong: #5f7ad3;
      --color-focus: #8fb3ff;
      --color-accent: #7aa2ff;
      --color-accent-strong: #a9c1ff;
      --color-button-text: #081224;
      --color-shadow: #050814;
      --color-success: #7ef0b0;
    }

