        border-color: ButtonBorder;
        box-shadow: none;
      }

      .radio-option label::before {
        border-color: ButtonText;
      }

      .radio-option input:checked + label::before {
        background: Highlight;
        box-shadow: inset 0 0 0 1px Highlight;
      }

      .radio-option input:focus-visible + label,
      button:focus-visible,
      .skip-link:focus {
        outline: 2px solid Highlight;
      }

      .skip-link {
        background: ButtonFace;
        color: ButtonText;
      }

      .status-message {
        color: CanvasText;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>
  <script>
    const notificationOptions = [
      { id: "notifications-email", value: "Email", label: "Email" },
      { id: "notifications-sms", value: "SMS", label: "SMS" },
      { id: "notifications-push", value: "Push Notifications", label: "Push Notifications" }
    ];

    const RadioOption = ({ id, value, label }) => `
      <div class="radio-option">
        <input id="${id}" name="notificationPreference" type="radio" value="${value}" required>
        <label for="${id}">${label}</label>
      </div>
    `;

    const NotificationPreferenceField = () => `
      <div class="form-field">
        <fieldset aria-describedby="notification-help">
          <legend>
            How do you prefer to receive notifications?
            <span class="required-mark" aria-hidden="true">*</span>
          </legend>
          <p id="notification-help" class="field-help">Choose one option before submitting the form.</p>
          <div class="radio-list">
            ${notificationOptions.map(RadioOption).join("")}
          </div>
        </fieldset>
      </div>
    `;

    const FormSection = () => `
      <section aria-labelledby="notification-preferences-title">
        <h1 id="notification-preferences-title">Notification preferences</h1>
        <p class="intro">Select the single notification method you want this account to use by default.</p>
        <p class="form-note"><span class="required-mark" aria-hidden="true">*</span> Required field</p>
        <form id="notification-form" novalidate>
          ${NotificationPreferenceField()}
          <div class="actions">
            <button type="submit">Submit preferences</button>
            <p id="form-status" class="status-message" role="status" aria-live="polite"></p>
          </div>
        </form>
      </section>
    `;

    const App = () => `
      <a class="skip-link" href="#maincontent">Skip to main content</a>
      <main id="maincontent" tabindex="-1">
        <div class="panel">
          ${FormSection()}
        </div>
      </main>
    `;

    document.getElementById("app").innerHTML = App();

    const form = document.getElementById("notification-form");
    const status = document.getElementById("form-status");

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      if (!form.checkValidity()) {
        form.reportValidity();
        const invalidControl = form.querySelector(":invalid");
        if (invalidControl) {
          invalidControl.focus();
        }
        status.textContent = "";
        return;
      }

      const formData = new FormData(form);
      const choice = formData.get("notificationPreference");
      status.textContent = `Preference saved: ${choice}.`;
    });
  </script>
</body>
</html>
